        "1e8fedfdba224516bd9772f4bd44c2e4": {
          "id": "1e8fedfdba224516bd9772f4bd44c2e4",
          "name": "call gemini",
          "script": "(function execute() {\n    try {\n        var r = new sn_ws.RESTMessageV2('Gemini', 'Query');\n        r.setStringParameterNoEscape('prompt', vaInputs.get_you_question);\n        var response = r.execute();\n        var responseBody = response.getBody();\n        var httpStatus = response.getStatusCode();\n\n        if (httpStatus == '200') {\n            var data = JSON.parse(responseBody);\n            vaVars.gptAnswer = data.candidates[0].content.parts[0].text;\n        } else {\n            vaVars.gptAnswer = 'Error contacting Gemini: ' + httpStatus + ' - ' + responseBody;\n        }\n    } catch (ex) {\n        vaVars.gptAnswer = 'Error: ' + ex.message;\n    }\n})();",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
